/* ТАБЕЛЬ УЧЁТА РАБОЧЕГО ВРЕМЕНИ (по образцу Т-13) И ГРАФИКИ СМЕН.
   Производственный календарь РФ — внутри плагина: праздники, переносы по постановлениям
   Правительства и предпраздничные сокращённые дни на 2025–2027 годы. Для других лет —
   общее правило ТК РФ (ст. 112), и плагин честно предупреждает, что январские переносы неизвестны.
   Табель: на каждого сотрудника две строки — коды (Я, В, ОТ, Б…) и часы; итоги — формулами.
   График смен: 5/2, 2/2, сутки через трое, день-ночь-отсыпной-выходной или свой цикл;
   отклонение от нормы часов считается формулой и подсвечивается. */

/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}

const МЕСЯЦЫ = ['январь', 'февраль', 'март', 'апрель', 'май', 'июнь', 'июль', 'август', 'сентябрь', 'октябрь', 'ноябрь', 'декабрь'];
const МЕСЯЦА = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];
const ДНИ = ['вс', 'пн', 'вт', 'ср', 'чт', 'пт', 'сб'];
const ПРАЗДНИКИ = ['01-01', '01-02', '01-03', '01-04', '01-05', '01-06', '01-07', '01-08', '02-23', '03-08', '05-01', '05-09', '06-12', '11-04'];
/* Постановления Правительства РФ о переносе выходных: 2025 — № 1335 от 04.10.2024, 2026 — № 1466 от 24.09.2025,
   2027 — № 1187 от 17.09.2026. «выходные» — дополнительные нерабочие (переносы, в том числе по ст. 112 ТК РФ),
   «рабочие» — рабочие субботы, «короткие» — дни, сокращённые на час. */
const КАЛЕНДАРЬ = {
  2025: {выходные: ['05-02', '05-08', '06-13', '11-03', '12-31'], рабочие: ['11-01'], короткие: ['03-07', '04-30', '06-11', '11-01']},
  2026: {выходные: ['01-09', '03-09', '05-11', '12-31'], рабочие: [], короткие: ['04-30', '05-08', '06-11', '11-03']},
  2027: {выходные: ['02-22', '05-03', '05-10', '06-14', '11-05', '12-31'], рабочие: ['02-20'], короткие: ['02-20', '04-30', '06-11', '11-03']},
};
const КОДЫ = ['Я', 'Н', 'РВ', 'С', 'К', 'ПК', 'ОТ', 'ОД', 'У', 'ДО', 'ОЗ', 'Р', 'ОЖ', 'Б', 'Т', 'Г', 'ПР', 'НН', 'В', 'ОВ', 'НВ'];
const ЯВКИ = ['Я', 'Н', 'РВ', 'С', 'К', 'ПК'];
const ДВА = n => String(n).padStart(2, '0');

/* --- календарь --- */
function календарьГода(y){
  const к = КАЛЕНДАРЬ[y];
  if(к) return {выходные: new Set(к.выходные), рабочие: new Set(к.рабочие), короткие: new Set(к.короткие), известен: true};
  /* общее правило: праздник на выходном — выходной переносится на следующий рабочий день (кроме января) */
  const выходные = new Set(), короткие = new Set();
  const деньНедели = (m, d) => new Date(Date.UTC(y, m - 1, d)).getUTCDay();
  const нерабочий = (m, d) => { const k = ДВА(m) + '-' + ДВА(d), w = деньНедели(m, d); return w === 0 || w === 6 || ПРАЗДНИКИ.includes(k) || выходные.has(k); };
  for(const k of ПРАЗДНИКИ){
    const [m, d] = k.split('-').map(Number);
    if(m === 1) continue;
    const w = деньНедели(m, d);
    if(w === 0 || w === 6){
      let x = new Date(Date.UTC(y, m - 1, d + 1));
      while(нерабочий(x.getUTCMonth() + 1, x.getUTCDate())) x = new Date(x.getTime() + 86400000);
      выходные.add(ДВА(x.getUTCMonth() + 1) + '-' + ДВА(x.getUTCDate()));
    }
  }
  for(const k of ПРАЗДНИКИ){
    const [m, d] = k.split('-').map(Number);
    const x = new Date(Date.UTC(y, m - 1, d - 1)), mm = x.getUTCMonth() + 1, dd = x.getUTCDate();
    if(!нерабочий(mm, dd) && x.getUTCFullYear() === y) короткие.add(ДВА(mm) + '-' + ДВА(dd));
  }
  return {выходные, рабочие: new Set(), короткие, известен: false};
}
function деньМесяца(y, m, d, кал){
  const k = ДВА(m) + '-' + ДВА(d), w = new Date(Date.UTC(y, m - 1, d)).getUTCDay();
  const праздник = ПРАЗДНИКИ.includes(k);
  const рабочий = кал.рабочие.has(k) || (!праздник && !кал.выходные.has(k) && w !== 0 && w !== 6);
  return {d, w, праздник, рабочий, короткий: рабочий && кал.короткие.has(k)};
}
function месяц(y, m){
  const кал = календарьГода(y), n = new Date(Date.UTC(y, m, 0)).getUTCDate(), дни = [];
  for(let d = 1; d <= n; d++) дни.push(деньМесяца(y, m, d, кал));
  return {y, m, дни, известен: кал.известен};
}
function норма(мес, часовВНеделю){
  const вДень = часовВНеделю / 5;
  const рабочих = мес.дни.filter(x => x.рабочий).length, коротких = мес.дни.filter(x => x.короткий).length;
  return {дней: рабочих, часов: Math.round((рабочих * вДень - коротких) * 10) / 10, коротких};
}
function выбранныйМесяц(п){
  const m = Math.max(1, МЕСЯЦЫ.indexOf(String(п.месяц || '').toLowerCase()) + 1);
  const y = Math.round(+п.год) || new Date().getFullYear();
  return месяц(y, m);
}

/* --- список сотрудников --- */
const ЗАГ_СПИСКА = {фио: /^(фио|ф\.и\.о|сотрудник|работник|фамилия|имя)/i, номер: /^(таб|табельный|№ таб|номер)/i, должность: /^(должность|профессия|позиция)/i};
let список = null;
async function ВзятьСписок(){
  const в = книга.выделение;
  if(!в || !в.область){ панель.сообщение('Выделите список сотрудников (можно с заголовками ФИО, Таб. №, Должность).'); return; }
  const строки = await диапазон(в.область).прочитать();
  const шапка = (строки[0] || []).map(x => String(x == null ? '' : x).trim());
  const где = {};
  for(const [поле, re] of Object.entries(ЗАГ_СПИСКА)){ const i = шапка.findIndex(x => re.test(x)); if(i >= 0) где[поле] = i; }
  const сШапкой = Object.keys(где).length > 0;
  if(где.фио === undefined) где.фио = 0;
  список = (сШапкой ? строки.slice(1) : строки).filter(р => р[где.фио] != null && String(р[где.фио]).trim())
    .map(р => ({фио: String(р[где.фио]).trim(), номер: где.номер !== undefined && р[где.номер] != null ? String(р[где.номер]) : '', должность: где.должность !== undefined && р[где.должность] != null ? String(р[где.должность]) : ''}));
  хранилище.положить('сотрудники', список);
  панель.список('сотрудники', [['Сотрудников', String(список.length)]].concat(список.slice(0, 8).map((x, i) => [String(i + 1), x.фио + (x.должность ? ', ' + x.должность : '')])));
  панель.сообщение('Взято сотрудников: ' + список.length + '. Перейдите на пустой лист и нажмите «Сделать табель» или «Сделать график».');
}
function сотрудники(){ if(!список) список = хранилище.взять('сотрудники', null); return список && список.length ? список : null; }

/* --- общая разметка сетки по дням --- */
const ШАПКА = {b: 1, size: 9, align: 'center', valign: 'middle', wrap: 1, гр: РАМКА('тонкая', '#151c2e')};
const ЯЧ = {size: 9, align: 'center', valign: 'middle', гр: РАМКА('тонкая', '#9aa4b5')};
const КРАСНЫЙ = '#dc2626';
/* сетка: столбцы — № | сотрудник | таб. № | дни 1–15 | итог I | дни 16–… | итог II | дальше — итоги */
function столбцыДней(мес){
  const out = []; let c = 3;
  мес.дни.forEach((x, i) => { if(i === 15){ out.push({итогI: true, c: c++}); } out.push({день: x, c: c++}); });
  out.push({итогII: true, c: c++});
  return {столбцы: out, дальше: c};
}
async function начатьЛист(высота, ширина){
  if(!(await областьПуста(0, 0, высота, ширина))){
    if(!(await диалог.вопрос('Лист не пустой — табель ляжет поверх (с A1). Лучше завести пустой лист (+ внизу). Продолжить?'))) return false;
  }
  return true;
}

/* ===== Табель ===== */
async function Табель(){
  const п = параметры({}), люди = сотрудники();
  if(!люди){ панель.сообщение('Сначала выделите список сотрудников и нажмите «Взять список».'); return; }
  const мес = выбранныйМесяц(п), часовВНеделю = +(String(п.неделя || '40').match(/\d+/) || [40])[0], вДень = часовВНеделю / 5;
  const н = норма(мес, часовВНеделю);
  const {столбцы, дальше} = столбцыДней(мес);
  const R0 = 6, всего = R0 + 2 + люди.length * 2 + 4;
  if(!(await начатьЛист(всего, дальше + 6))) return;
  const л = Api.GetActiveSheet();
  клетка(0, 0).значение = 'Табель учёта рабочего времени'; клетка(0, 0).стиль = {b: 1, size: 13};
  клетка(1, 0).значение = 'за ' + МЕСЯЦЫ[мес.m - 1] + ' ' + мес.y + ' г. · отчётный период 01.' + ДВА(мес.m) + '.' + мес.y + ' — ' + ДВА(мес.дни.length) + '.' + ДВА(мес.m) + '.' + мес.y;
  клетка(2, 0).значение = 'Норма: ' + н.дней + ' раб. дней, ' + String(н.часов).replace('.', ',') + ' ч (' + часовВНеделю + '-часовая неделя' + (н.коротких ? ', предпраздничных дней: ' + н.коротких : '') + ')';
  клетка(2, 0).стиль = {color: '#5b6b86'};
  клетка(3, 0).значение = (мес.известен ? 'Производственный календарь РФ на ' + мес.y + ' год.' : 'Внимание: переносы выходных на ' + мес.y + ' год плагину неизвестны — календарь по общему правилу ТК РФ, проверьте январь.')
    + ' Форма — по образцу унифицированной Т-13 (основные графы).';
  клетка(3, 0).стиль = {size: 8, i: 1, color: мес.известен ? '#5b6b86' : КРАСНЫЙ};
  /* шапка */
  const h1 = R0, h2 = R0 + 1;
  const шапка = (r, c, т, ст) => { const к = клетка(r, c); к.значение = т; к.стиль = Object.assign({}, ШАПКА, ст || {}); };
  [['№', 0], ['Сотрудник, должность', 1], ['Таб. №', 2]].forEach(([т, c]) => { шапка(h1, c, т); шапка(h2, c, ''); л.GetRange(ОБЛАСТЬ(h1, c, h2, c)).Merge(false); });
  for(const x of столбцы){
    if(x.день){ шапка(h1, x.c, x.день.d, x.день.рабочий ? {} : {color: КРАСНЫЙ}); шапка(h2, x.c, ДНИ[x.день.w] + (x.день.короткий ? '*' : ''), {b: 0, size: 8, color: x.день.рабочий ? '#5b6b86' : КРАСНЫЙ}); }
    else { шапка(h1, x.c, x.итогI ? 'Итого I пол.' : 'Итого II пол.', {size: 8}); шапка(h2, x.c, 'ч', {b: 0, size: 8}); }
  }
  const ИТОГИ = ['Дней', 'Часов', 'ОТ, дн.', 'Б, дн.', 'Другие неявки, дн.'];
  ИТОГИ.forEach((т, k) => { шапка(h1, дальше + k, т, {size: 8}); шапка(h2, дальше + k, '', {}); л.GetRange(ОБЛАСТЬ(h1, дальше + k, h2, дальше + k)).Merge(false); });
  /* строки сотрудников */
  const кодов = '"' + КОДЫ.join(',') + '"';
  const перв = столбцы.find(x => x.день).c, посл = столбцы.filter(x => x.день).pop().c;
  const I = столбцы.find(x => x.итогI), II = столбцы.find(x => x.итогII);
  люди.forEach((ч, i) => {
    const rк = R0 + 2 + i * 2, rч = rк + 1, nк = rк + 1, nч = rч + 1;
    клетка(rк, 0).значение = i + 1; клетка(rк, 0).стиль = ЯЧ; клетка(rч, 0).стиль = ЯЧ; л.GetRange(ОБЛАСТЬ(rк, 0, rч, 0)).Merge(false);
    клетка(rк, 1).значение = ч.фио + (ч.должность ? ', ' + ч.должность : ''); клетка(rк, 1).стиль = Object.assign({}, ЯЧ, {align: 'left', wrap: 1}); клетка(rч, 1).стиль = ЯЧ; л.GetRange(ОБЛАСТЬ(rк, 1, rч, 1)).Merge(false);
    клетка(rк, 2).значение = ч.номер; клетка(rк, 2).стиль = ЯЧ; клетка(rч, 2).стиль = ЯЧ; л.GetRange(ОБЛАСТЬ(rк, 2, rч, 2)).Merge(false);
    for(const x of столбцы){
      if(x.день){
        клетка(rк, x.c).значение = x.день.рабочий ? 'Я' : 'В';
        клетка(rк, x.c).стиль = Object.assign({}, ЯЧ, {color: x.день.рабочий ? '#151c2e' : КРАСНЫЙ});
        клетка(rч, x.c).значение = x.день.рабочий ? (x.день.короткий ? вДень - 1 : вДень) : '';
        клетка(rч, x.c).стиль = ЯЧ;
      } else {
        const от = x.итогI ? перв : I.c + 1, до = x.итогI ? I.c - 1 : посл;
        клетка(rк, x.c).стиль = ЯЧ;
        клетка(rч, x.c).формула = 'СУММ(' + БУКВА(от) + nч + ':' + БУКВА(до) + nч + ')'; клетка(rч, x.c).стиль = Object.assign({}, ЯЧ, {b: 1});
      }
    }
    л.GetRange(ОБЛАСТЬ(rк, перв, rк, посл)).GetValidation().Add('xlValidateList', 'xlValidAlertStop', null, кодов);
    const коды = '$' + БУКВА(перв) + '$' + nк + ':$' + БУКВА(посл) + '$' + nк;
    const явки = ЯВКИ.map(к => 'СЧЁТЕСЛИ(' + коды + ';"' + к + '")').join('+');
    const ф = [явки, БУКВА(I.c) + nч + '+' + БУКВА(II.c) + nч, 'СЧЁТЕСЛИ(' + коды + ';"ОТ")', 'СЧЁТЕСЛИ(' + коды + ';"Б")',
      'СЧЁТЗ(' + коды + ')-СЧЁТЕСЛИ(' + коды + ';"В")-(' + явки + ')-СЧЁТЕСЛИ(' + коды + ';"ОТ")-СЧЁТЕСЛИ(' + коды + ';"Б")'];
    ф.forEach((f, k) => { клетка(rк, дальше + k).формула = f; клетка(rк, дальше + k).стиль = Object.assign({}, ЯЧ, {b: k < 2 ? 1 : 0}); клетка(rч, дальше + k).стиль = ЯЧ; л.GetRange(ОБЛАСТЬ(rк, дальше + k, rч, дальше + k)).Merge(false); });
  });
  /* подписи и пояснения */
  const низ = R0 + 2 + люди.length * 2 + 1;
  клетка(низ, 1).значение = 'Коды: Я — явка, Н — ночные, РВ — выходной/праздник, С — сверхурочно, К — командировка, ОТ — ежегодный отпуск, ДО — без сохранения, Б — болезнь, НН — неявка по невыясненным причинам, ПР — прогул, В — выходной. * — предпраздничный день, короче на час.';
  клетка(низ, 1).стиль = {size: 8, color: '#5b6b86'};
  клетка(низ + 2, 1).значение = 'Ответственное лицо ____________________     Руководитель ____________________     Работник кадровой службы ____________________';
  клетка(низ + 2, 1).стиль = {size: 9};
  /* размеры */
  ширинаСтолбца(0, 28); ширинаСтолбца(1, 190); ширинаСтолбца(2, 50);
  for(const x of столбцы) ширинаСтолбца(x.c, x.день ? 26 : 44);
  for(let k = 0; k < ИТОГИ.length; k++) ширинаСтолбца(дальше + k, 50);
  высотаСтроки(h1, 30);
  await обновитьВысоты();
  лист().запомнить('печать', {область: null, шапка: R0 + 2, ориентация: 'landscape', бумага: 'A4', уместить: true, масштаб: 100, сетка: false, заголовки: false, название: false, поле: 8});
  показатьМесяц(мес, часовВНеделю);
  панель.сообщение('Табель на ' + МЕСЯЦЫ[мес.m - 1] + ' ' + мес.y + ': ' + люди.length + ' чел., норма ' + н.дней + ' дн. / ' + String(н.часов).replace('.', ',') + ' ч. Коды меняются выбором из списка, часы — числом; итоги считаются формулами.'
    + (мес.известен ? '' : ' Календарь на этот год — по общему правилу, переносы неизвестны.'));
}

/* ===== График смен ===== */
const ГРАФИКИ = {
  '5/2 — пятидневка':                    {цикл: null},
  '2/2 — два через два':                 {цикл: ['Д', 'Д', 'В', 'В']},
  'сутки через трое':                    {цикл: ['С', 'В', 'В', 'В']},
  'день, ночь, отсыпной, выходной':      {цикл: ['Д', 'Н', 'О', 'В']},
  '3/3 — три через три':                 {цикл: ['Д', 'Д', 'Д', 'В', 'В', 'В']},
  'свой цикл':                           {цикл: 'свой'},
};
async function График(){
  const п = параметры({}), люди = сотрудники();
  if(!люди){ панель.сообщение('Сначала выделите список сотрудников и нажмите «Взять список».'); return; }
  const мес = выбранныйМесяц(п), часовВНеделю = +(String(п.неделя || '40').match(/\d+/) || [40])[0];
  const н = норма(мес, часовВНеделю);
  const вид = ГРАФИКИ[п.график] ? п.график : '2/2 — два через два';
  let цикл = ГРАФИКИ[вид].цикл;
  if(цикл === 'свой'){
    цикл = String(п.свойЦикл || '').toUpperCase().split(/[\s,;]+/).filter(Boolean);
    if(!цикл.length || цикл.some(x => !['Д', 'Н', 'С', 'В', 'О', 'Я'].includes(x))){ панель.сообщение('Свой цикл — коды через пробел: Д (день), Н (ночь), С (сутки), Я (8 ч), О (отсыпной), В (выходной). Например: Д Д Н Н В В В В'); return; }
  }
  const смена = Math.max(1, +п.смена || 12);
  const часыКода = {Д: смена, Н: смена, С: 24, Я: часовВНеделю / 5, О: 0, В: 0};
  const начало = (() => { const s = String(п.начало || ''); const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s); return m ? Date.UTC(+m[1], +m[2] - 1, +m[3]) : Date.UTC(мес.y, мес.m - 1, 1); })();
  const сдвиг = Math.round(+п.сдвиг || 0);
  const {столбцы, дальше} = столбцыДней(мес);
  const R0 = 6, всего = R0 + 2 + люди.length * 2 + 4;
  if(!(await начатьЛист(всего, дальше + 4))) return;
  const л = Api.GetActiveSheet();
  клетка(0, 0).значение = 'График работы: ' + вид + (цикл && вид === 'свой цикл' ? ' (' + цикл.join(' ') + ')' : '') + ', смена ' + смена + ' ч'; клетка(0, 0).стиль = {b: 1, size: 13};
  клетка(1, 0).значение = 'на ' + МЕСЯЦЫ[мес.m - 1] + ' ' + мес.y + ' г.';
  клетка(2, 0).значение = 'Норма по производственному календарю: ' + String(н.часов).replace('.', ',') + ' ч (' + часовВНеделю + '-часовая неделя). Переработка — красным, недоработка — синим.';
  клетка(2, 0).стиль = {color: '#5b6b86'};
  if(!мес.известен){ клетка(3, 0).значение = 'Переносы выходных на ' + мес.y + ' год плагину неизвестны — норма по общему правилу ТК РФ.'; клетка(3, 0).стиль = {size: 8, i: 1, color: КРАСНЫЙ}; }
  const h1 = R0, h2 = R0 + 1;
  const шапка = (r, c, т, ст) => { const к = клетка(r, c); к.значение = т; к.стиль = Object.assign({}, ШАПКА, ст || {}); };
  [['№', 0], ['Сотрудник', 1], ['Таб. №', 2]].forEach(([т, c]) => { шапка(h1, c, т); шапка(h2, c, ''); л.GetRange(ОБЛАСТЬ(h1, c, h2, c)).Merge(false); });
  for(const x of столбцы){
    if(x.день){ шапка(h1, x.c, x.день.d, x.день.рабочий ? {} : {color: КРАСНЫЙ}); шапка(h2, x.c, ДНИ[x.день.w], {b: 0, size: 8, color: x.день.рабочий ? '#5b6b86' : КРАСНЫЙ}); }
    else { шапка(h1, x.c, x.итогI ? 'I пол.' : 'II пол.', {size: 8}); шапка(h2, x.c, 'ч', {b: 0, size: 8}); }
  }
  ['Часов', 'Норма', 'Отклонение'].forEach((т, k) => { шапка(h1, дальше + k, т, {size: 8}); шапка(h2, дальше + k, '', {}); л.GetRange(ОБЛАСТЬ(h1, дальше + k, h2, дальше + k)).Merge(false); });
  const перв = столбцы.find(x => x.день).c, посл = столбцы.filter(x => x.день).pop().c;
  const I = столбцы.find(x => x.итогI), II = столбцы.find(x => x.итогII);
  /* норма — отдельной клеткой, отклонения считаются от неё */
  const нормаАдр = '$' + БУКВА(дальше + 1) + '$' + (R0 + 3);
  const итоги = [];
  люди.forEach((ч, i) => {
    const rк = R0 + 2 + i * 2, rч = rк + 1, nч = rч + 1;
    клетка(rк, 0).значение = i + 1; клетка(rк, 0).стиль = ЯЧ; клетка(rч, 0).стиль = ЯЧ; л.GetRange(ОБЛАСТЬ(rк, 0, rч, 0)).Merge(false);
    клетка(rк, 1).значение = ч.фио; клетка(rк, 1).стиль = Object.assign({}, ЯЧ, {align: 'left'}); клетка(rч, 1).стиль = ЯЧ; л.GetRange(ОБЛАСТЬ(rк, 1, rч, 1)).Merge(false);
    клетка(rк, 2).значение = ч.номер; клетка(rк, 2).стиль = ЯЧ; клетка(rч, 2).стиль = ЯЧ; л.GetRange(ОБЛАСТЬ(rк, 2, rч, 2)).Merge(false);
    let часов = 0;
    for(const x of столбцы){
      if(x.день){
        let код;
        if(!цикл) код = x.день.рабочий ? 'Я' : 'В';
        else {
          const k = Math.round((Date.UTC(мес.y, мес.m - 1, x.день.d) - начало) / 86400000) - i * сдвиг;
          код = цикл[((k % цикл.length) + цикл.length) % цикл.length];
        }
        const ч2 = код === 'Я' && x.день.короткий ? часыКода[код] - 1 : часыКода[код];
        часов += ч2;
        клетка(rк, x.c).значение = код;
        клетка(rк, x.c).стиль = Object.assign({}, ЯЧ, {color: код === 'В' || код === 'О' ? '#9aa4b5' : код === 'Н' ? '#1e3a8a' : '#151c2e', b: код === 'В' || код === 'О' ? 0 : 1});
        /* часы — формулой от кода: поменяли код — часы пересчитались */
        const к = БУКВА(x.c) + (rк + 1), я = часыКода.Я - (x.день.короткий ? 1 : 0);
        клетка(rч, x.c).формула = 'ЕСЛИ(' + к + '="Д";' + смена + ';ЕСЛИ(' + к + '="Н";' + смена + ';ЕСЛИ(' + к + '="С";24;ЕСЛИ(' + к + '="Я";' + я + ';0))))';
        клетка(rч, x.c).стиль = Object.assign({}, ЯЧ, {fmt: '0;-0;;@'});
      } else {
        const от = x.итогI ? перв : I.c + 1, до = x.итогI ? I.c - 1 : посл;
        клетка(rк, x.c).стиль = ЯЧ;
        клетка(rч, x.c).формула = 'СУММ(' + БУКВА(от) + nч + ':' + БУКВА(до) + nч + ')'; клетка(rч, x.c).стиль = Object.assign({}, ЯЧ, {b: 1});
      }
    }
    const ф = [БУКВА(I.c) + nч + '+' + БУКВА(II.c) + nч, i ? нормаАдр : null, БУКВА(дальше) + (rк + 1) + '-' + БУКВА(дальше + 1) + (rк + 1)];
    ф.forEach((f, k) => { if(f) клетка(rк, дальше + k).формула = f; else клетка(rк, дальше + k).значение = н.часов;
      клетка(rк, дальше + k).стиль = Object.assign({}, ЯЧ, {b: 1}); клетка(rч, дальше + k).стиль = ЯЧ; л.GetRange(ОБЛАСТЬ(rк, дальше + k, rч, дальше + k)).Merge(false); });
    итоги.push(часов);
  });
  /* норма — числом у первого сотрудника, у остальных ссылкой на неё; отклонение красим правилами */
  const откл = л.GetRange(ОБЛАСТЬ(R0 + 2, дальше + 2, R0 + 1 + люди.length * 2, дальше + 2));
  try { откл.GetFormatConditions().Add('xlCellValue', 'xlGreater', '0').SetFontColor(Api.CreateColorFromRGB(220, 38, 38)); } catch(e){}
  try { откл.GetFormatConditions().Add('xlCellValue', 'xlLess', '0').SetFontColor(Api.CreateColorFromRGB(37, 99, 235)); } catch(e){}
  for(let i = 0; i < люди.length; i++) л.GetRange(ОБЛАСТЬ(R0 + 2 + i * 2, перв, R0 + 2 + i * 2, посл)).GetValidation().Add('xlValidateList', 'xlValidAlertStop', null, '"Д,Н,С,Я,О,В"');
  ширинаСтолбца(0, 28); ширинаСтолбца(1, 170); ширинаСтолбца(2, 50);
  for(const x of столбцы) ширинаСтолбца(x.c, x.день ? 26 : 44);
  for(let k = 0; k < 3; k++) ширинаСтолбца(дальше + k, 64);
  высотаСтроки(h1, 30);
  await обновитьВысоты();
  лист().запомнить('печать', {область: null, шапка: R0 + 2, ориентация: 'landscape', бумага: 'A4', уместить: true, масштаб: 100, сетка: false, заголовки: false, название: false, поле: 8});
  показатьМесяц(мес, часовВНеделю);
  const больше = итоги.filter(x => x > н.часов).length, меньше = итоги.filter(x => x < н.часов).length;
  панель.сообщение('График: ' + люди.length + ' чел., ' + вид + '. Норма месяца ' + String(н.часов).replace('.', ',') + ' ч; выше нормы — ' + больше + ', ниже — ' + меньше
    + '. При суммированном учёте сравнивайте с нормой учётного периода, а не месяца.');
}

/* ===== Календарь в панели ===== */
function показатьМесяц(мес, часовВНеделю){
  const н = норма(мес, часовВНеделю || 40);
  const праздники = мес.дни.filter(x => !x.рабочий && x.w !== 0 && x.w !== 6).map(x => x.d + (x.праздник ? '' : ' (перенос)'));
  const рабочиеВых = мес.дни.filter(x => x.рабочий && (x.w === 0 || x.w === 6)).map(x => x.d);
  панель.список('календарь', [
    ['Месяц', МЕСЯЦЫ[мес.m - 1] + ' ' + мес.y], ['Рабочих дней', String(н.дней)], ['Календарных', String(мес.дни.length)],
    ['Норма часов', String(н.часов).replace('.', ',') + ' (' + (часовВНеделю || 40) + ' ч/нед.)'],
    ['Праздники и переносы в будни', праздники.join(', ') || '—'], ['Рабочие выходные', рабочиеВых.join(', ') || '—'],
    ['Сокращённые дни', мес.дни.filter(x => x.короткий).map(x => x.d + ' ' + МЕСЯЦА[мес.m - 1]).join(', ') || '—'],
    ['Источник', мес.известен ? 'постановление Правительства РФ о переносах на ' + мес.y + ' год' : 'общее правило ТК РФ — переносы неизвестны']]);
}
function Календарь(){ const п = параметры({}); показатьМесяц(выбранныйМесяц(п), +(String(п.неделя || '40').match(/\d+/) || [40])[0]); }
function Старт(){
  /* по умолчанию — текущий месяц */
  const сейчас = new Date();
  панель.поле('месяц', МЕСЯЦЫ[сейчас.getMonth()]); панель.поле('год', сейчас.getFullYear());
  const л = хранилище.взять('сотрудники', null);
  if(л) панель.список('сотрудники', [['Сотрудников', String(л.length)]]);
  показатьМесяц(месяц(сейчас.getFullYear(), сейчас.getMonth() + 1), 40);
}
